INSERT INTO "Recipes" ("id", "time", "preferences", "rating", "ratingCount", "name", "description", "difficulty", "imageFileId", "tags", "substitutions", "source", "createdDate", "updatedDate", "userId", "isFavorite") VALUES ('f08fc0c7-423a-4b66-b48f-c761da27e13f'::uuid, 15, NULL, NULL, 0, '番茄嫩豆腐鸡蛋汤'::text, '番茄酸润开胃，嫩豆腐滑嫩，蛋花轻盈，整体清淡爽口，适合15分钟左右快速完成。'::text, '简单'::text, NULL, '["家常菜","汤羹","清淡爽口","快手"]'::jsonb, '[]'::jsonb, 'ai_generated'::text, '2026-09-03T14:08:30.073284+08:00'::timestamptz, '2026-09-03T14:08:30.073284+08:00'::timestamptz, 'c0ef3510-03b3-4024-a1e3-d85e53f2eb81'::uuid, TRUE) ON CONFLICT DO NOTHING;
