INSERT INTO "Ingredients" ("id", "name", "quantity", "unitTypeId", "locationId", "userId", "expiryDate", "updatedDate", "normalizedName", "imageFileId", "source", "createdDate") VALUES ('1bbde025-44f3-4a91-a9dd-7bb095ba402d'::uuid, '彩椒'::text, 2, 1, '43753b58-40cd-48f7-b2da-2e018fddf3a8'::uuid, 'c0ef3510-03b3-4024-a1e3-d85e53f2eb81'::uuid, NULL, '2026-09-04T16:37:31.306917+08:00'::timestamptz, '彩椒'::text, NULL, 'recognition'::text, '2026-09-04T16:37:31.306917+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "Ingredients" ("id", "name", "quantity", "unitTypeId", "locationId", "userId", "expiryDate", "updatedDate", "normalizedName", "imageFileId", "source", "createdDate") VALUES ('64078bf8-9931-4009-b9a6-f4aa85630203'::uuid, '西兰花'::text, 1, 4, '43753b58-40cd-48f7-b2da-2e018fddf3a8'::uuid, 'c0ef3510-03b3-4024-a1e3-d85e53f2eb81'::uuid, NULL, '2026-09-04T16:37:31.361769+08:00'::timestamptz, '西兰花'::text, NULL, 'recognition'::text, '2026-09-04T16:37:31.361769+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('e2ffa60e-50ab-4ad3-9ea9-3547f4bed050'::uuid, 'f08fc0c7-423a-4b66-b48f-c761da27e13f'::uuid, 1, '处理食材'::text, '番茄洗净切小块；嫩豆腐切成小方块；鸡蛋打入碗中搅散备用。'::text, 3, '2026-09-03T14:08:30.251842+08:00'::timestamptz, '2026-09-03T14:08:30.251842+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('43855937-291f-43aa-a4ec-3f438534764b'::uuid, 'f08fc0c7-423a-4b66-b48f-c761da27e13f'::uuid, 2, '炒出番茄汁'::text, '锅中加少许油，放入番茄块中小火翻炒，炒至番茄变软出汁，可加少量盐帮助出汁。'::text, 3, '2026-09-03T14:08:30.251842+08:00'::timestamptz, '2026-09-03T14:08:30.251842+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('8071ff2b-fd6c-485b-b524-513d205fca3f'::uuid, 'f08fc0c7-423a-4b66-b48f-c761da27e13f'::uuid, 3, '加水煮汤'::text, '加入适量清水，大火烧开后放入嫩豆腐，转中小火煮3分钟左右，让豆腐热透。'::text, 4, '2026-09-03T14:08:30.251842+08:00'::timestamptz, '2026-09-03T14:08:30.251842+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('5ee3f737-e2d8-4bfc-be4a-b3a03d0c659b'::uuid, 'f08fc0c7-423a-4b66-b48f-c761da27e13f'::uuid, 4, '淋入蛋液'::text, '保持汤面微沸，将蛋液沿锅边缓缓淋入，待蛋花定型后轻轻搅动。'::text, 2, '2026-09-03T14:08:30.251842+08:00'::timestamptz, '2026-09-03T14:08:30.251842+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('3ebefef5-2a75-460a-835c-5df950226dd2'::uuid, 'f08fc0c7-423a-4b66-b48f-c761da27e13f'::uuid, 5, '调味出锅'::text, '根据口味加盐调味，可撒少许白胡椒粉，关火后滴几滴香油即可。'::text, 3, '2026-09-03T14:08:30.251842+08:00'::timestamptz, '2026-09-03T14:08:30.251842+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('3deab9c5-0de2-454d-87fd-706876aece15'::uuid, '7abb2e2a-b5fc-4961-b1c6-2cc53e7d893d'::uuid, 1, '准备食材'::text, '番茄洗净切小丁；嫩豆腐切小块；鸡蛋打散；生菜洗净撕成小片。'::text, 5, '2026-09-03T14:42:08.130995+08:00'::timestamptz, '2026-09-03T14:42:08.130995+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('a76e0258-4c03-46d5-b1d7-e6ced6a6b5a8'::uuid, '7abb2e2a-b5fc-4961-b1c6-2cc53e7d893d'::uuid, 2, '炒番茄出汁'::text, '锅中加少许清水，放入番茄丁，小火翻炒至番茄变软并渗出汤汁。'::text, 4, '2026-09-03T14:42:08.130995+08:00'::timestamptz, '2026-09-03T14:42:08.130995+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('5ec24c8b-afcf-4ccf-993d-1ddd10f29fa9'::uuid, '7abb2e2a-b5fc-4961-b1c6-2cc53e7d893d'::uuid, 3, '加水煮豆腐'::text, '加入清水，放入嫩豆腐，中火煮至汤面微沸。'::text, 5, '2026-09-03T14:42:08.130995+08:00'::timestamptz, '2026-09-03T14:42:08.130995+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('08a70026-3b69-4531-adc2-c6e4e7985ab5'::uuid, '7abb2e2a-b5fc-4961-b1c6-2cc53e7d893d'::uuid, 4, '淋蛋液加生菜'::text, '转小火，将蛋液画圈淋入汤中，形成蛋花后加入生菜烫软。'::text, 3, '2026-09-03T14:42:08.130995+08:00'::timestamptz, '2026-09-03T14:42:08.130995+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('8501acc9-8860-447e-992c-3003d981269e'::uuid, '7abb2e2a-b5fc-4961-b1c6-2cc53e7d893d'::uuid, 5, '调味出锅'::text, '加盐调味，轻轻搅匀后即可出锅。'::text, 3, '2026-09-03T14:42:08.130995+08:00'::timestamptz, '2026-09-03T14:42:08.130995+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('333fee5b-dcb4-4cbc-ad06-561bc4a0aa88'::uuid, 'a161b9f6-3b95-4697-9fe7-e2cfa9a20f0f'::uuid, 1, '腌制猪里脊'::text, '猪里脊切薄片或细条，加入生抽、料酒、少许黑椒、淀粉和少量鸡蛋液抓匀，再淋少许食用油锁住水分，腌制 10 分钟。'::text, 10, '2026-09-03T15:00:29.859044+08:00'::timestamptz, '2026-09-03T15:00:29.859044+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('144056bb-1bc5-4748-bb58-dca4a9226395'::uuid, 'a161b9f6-3b95-4697-9fe7-e2cfa9a20f0f'::uuid, 2, '处理青椒'::text, '青椒去籽，切成滚刀块或细丝备用。'::text, 2, '2026-09-03T15:00:29.859044+08:00'::timestamptz, '2026-09-03T15:00:29.859044+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('d9e0db27-cd55-464e-964e-9124b5c2d2a6'::uuid, 'a161b9f6-3b95-4697-9fe7-e2cfa9a20f0f'::uuid, 3, '滑炒猪里脊'::text, '热锅倒油，油热后放入腌好的猪里脊，快速翻炒至变色后盛出，避免炒老。'::text, 3, '2026-09-03T15:00:29.859044+08:00'::timestamptz, '2026-09-03T15:00:29.859044+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('bb9dce7d-0030-4224-8044-df70f46857b7'::uuid, 'a161b9f6-3b95-4697-9fe7-e2cfa9a20f0f'::uuid, 4, '炒青椒'::text, '锅中留底油，放入青椒翻炒至断生，撒少许盐调味。'::text, 2, '2026-09-03T15:00:29.859044+08:00'::timestamptz, '2026-09-03T15:00:29.859044+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('898dd22d-a9ef-49aa-921e-c82608efab29'::uuid, 'a161b9f6-3b95-4697-9fe7-e2cfa9a20f0f'::uuid, 5, '回锅调味'::text, '将炒好的猪里脊倒回锅中，加入黑椒和少量生抽，快速翻炒均匀即可出锅。'::text, 3, '2026-09-03T15:00:29.859044+08:00'::timestamptz, '2026-09-03T15:00:29.859044+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('674dbed2-29d6-47f0-8de7-f717e5efff07'::uuid, 'd9477437-a106-45bf-b971-8470fc3aefb5'::uuid, 1, '腌制猪里脊'::text, '猪里脊切成条或薄片，加入料酒、少许盐、半茶匙黑椒、鸡蛋清和淀粉抓匀，腌制 15 分钟，让肉更嫩更入味。'::text, 15, '2026-09-03T16:14:50.372691+08:00'::timestamptz, '2026-09-03T16:14:50.372691+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('125a555e-2720-4180-b1c8-09e39fb1cfe7'::uuid, 'd9477437-a106-45bf-b971-8470fc3aefb5'::uuid, 2, '煎嫩豆腐'::text, '嫩豆腐切块，锅中倒油烧热，放入豆腐小火慢煎，煎至两面微黄定型后盛出备用。'::text, 8, '2026-09-03T16:14:50.372691+08:00'::timestamptz, '2026-09-03T16:14:50.372691+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('3757817f-c769-455f-8cf6-fee9fb55ca69'::uuid, 'd9477437-a106-45bf-b971-8470fc3aefb5'::uuid, 3, '炒番茄和青椒'::text, '番茄切块，青椒去籽切块。锅中留底油，先炒番茄至出汁，再加入青椒翻炒出香味。'::text, 5, '2026-09-03T16:14:50.372691+08:00'::timestamptz, '2026-09-03T16:14:50.372691+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('736b15e7-5eee-4487-bb79-ae16d58c43cc'::uuid, 'd9477437-a106-45bf-b971-8470fc3aefb5'::uuid, 4, '滑炒猪里脊'::text, '另起锅热油，将腌好的猪里脊中火炒至刚变色，盛出避免炒老。'::text, 5, '2026-09-03T16:14:50.372691+08:00'::timestamptz, '2026-09-03T16:14:50.372691+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('e42770b6-5e33-46d8-972e-ca2617a5e371'::uuid, 'd9477437-a106-45bf-b971-8470fc3aefb5'::uuid, 5, '黑椒合烧'::text, '在番茄青椒锅中加入生抽、老抽、剩余黑椒和少量清水，放入煎好的嫩豆腐和猪里脊，小火慢烧 10 分钟，让豆腐吸满浓汁。'::text, 10, '2026-09-03T16:14:50.372691+08:00'::timestamptz, '2026-09-03T16:14:50.372691+08:00'::timestamptz) ON CONFLICT DO NOTHING;
INSERT INTO "RecipeSteps" ("id", "recipeId", "stepNumber", "title", "detailedInstructions", "time", "createdAt", "updatedAt") VALUES ('ff7ce7ba-d0ec-45dc-813a-b8963c74c5c1'::uuid, 'd9477437-a106-45bf-b971-8470fc3aefb5'::uuid, 6, '收汁出锅'::text, '转中火略收浓汤汁，尝味后可适量补盐，保持黑椒味浓、酱香重口即可出锅。'::text, 2, '2026-09-03T16:14:50.372691+08:00'::timestamptz, '2026-09-03T16:14:50.372691+08:00'::timestamptz) ON CONFLICT DO NOTHING;
